PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS restaurants (id TEXT PRIMARY KEY, currency TEXT NOT NULL DEFAULT 'USD', menu_revision INTEGER NOT NULL DEFAULT 1, hero_revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS site_content (restaurant_id TEXT PRIMARY KEY REFERENCES restaurants(id), title TEXT NOT NULL DEFAULT 'Menyue', description TEXT, cta_label TEXT, cta_url TEXT, hero_asset_id TEXT);
CREATE TABLE IF NOT EXISTS media_assets (id TEXT PRIMARY KEY, r2_key TEXT UNIQUE NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS menu_categories (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id), code TEXT NOT NULL, name TEXT NOT NULL, description TEXT, position INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, UNIQUE(restaurant_id, code));
CREATE TABLE IF NOT EXISTS menu_items (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES menu_categories(id), code TEXT NOT NULL, name TEXT NOT NULL, description TEXT, base_price_minor INTEGER NOT NULL CHECK(base_price_minor >= 0), allergy_note TEXT, photo_asset_id TEXT REFERENCES media_assets(id), position INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, UNIQUE(category_id, code));
CREATE TABLE IF NOT EXISTS item_promotions (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES menu_items(id), label TEXT NOT NULL, description TEXT, price_minor INTEGER, starts_at TEXT, ends_at TEXT, enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at));
CREATE TABLE IF NOT EXISTS allergens (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS item_allergens (item_id TEXT NOT NULL REFERENCES menu_items(id), allergen_id TEXT NOT NULL REFERENCES allergens(id), severity TEXT NOT NULL CHECK(severity IN ('contains','may_contain')), PRIMARY KEY(item_id, allergen_id));
CREATE TABLE IF NOT EXISTS combo_groups (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES menu_items(id), name TEXT NOT NULL, min_choices INTEGER NOT NULL DEFAULT 0, max_choices INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, CHECK(min_choices >= 0 AND max_choices >= min_choices));
CREATE TABLE IF NOT EXISTS combo_choices (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES combo_groups(id), code TEXT NOT NULL, name TEXT NOT NULL, price_delta_minor INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(group_id, code));
CREATE TABLE IF NOT EXISTS dining_tables (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id), label TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, token_hint TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(restaurant_id,label));
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','manager')), password_hash TEXT NOT NULL, salt TEXT NOT NULL, iterations INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, must_change_password INTEGER NOT NULL DEFAULT 0, auth_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS counter_credentials (id INTEGER PRIMARY KEY CHECK(id=1), password_hash TEXT NOT NULL, salt TEXT NOT NULL, iterations INTEGER NOT NULL, auth_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, principal_type TEXT NOT NULL CHECK(principal_type IN ('user','counter')), principal_id TEXT NOT NULL, auth_version INTEGER NOT NULL, csrf_hash TEXT NOT NULL, expires_at TEXT NOT NULL, absolute_expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id), display_number INTEGER NOT NULL, table_id TEXT NOT NULL REFERENCES dining_tables(id), idempotency_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','accepted','preparing','ready','completed','cancelled')), total_minor INTEGER NOT NULL, currency TEXT NOT NULL, note TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(table_id,idempotency_key), UNIQUE(restaurant_id,display_number));
CREATE TABLE IF NOT EXISTS order_lines (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), item_id TEXT NOT NULL, item_name TEXT NOT NULL, unit_minor INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20), total_minor INTEGER NOT NULL, promotion_label TEXT, allergy_snapshot TEXT);
CREATE TABLE IF NOT EXISTS order_line_choices (id TEXT PRIMARY KEY, line_id TEXT NOT NULL REFERENCES order_lines(id), group_name TEXT NOT NULL, choice_name TEXT NOT NULL, price_delta_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, detail_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS categories_public_idx ON menu_categories(restaurant_id, enabled, archived, position);
CREATE INDEX IF NOT EXISTS items_public_idx ON menu_items(category_id, enabled, archived, position);
CREATE INDEX IF NOT EXISTS orders_counter_idx ON orders(restaurant_id, created_at DESC);
